from pathlib import Path


def replace(path: str, old: str, new: str, count: int = 1) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"pattern not found in {path}: {old[:160]!r}")
    p.write_text(text.replace(old, new, count), encoding="utf-8")


Path("backend/core/openapi_contract.py").write_text(
    '''"""Validation helpers shared by offline OpenAPI export and tests."""\n\nfrom __future__ import annotations\n\nimport json\nfrom collections import Counter\nfrom typing import Any\n\nfrom fastapi.openapi.models import OpenAPI\n\n# These are intentionally a small, stable frontend contract rather than a\n# snapshot of every route. Adding a route does not churn this list; renaming a\n# consumed operation must be an explicit decision.\nCORE_OPERATION_IDS: dict[tuple[str, str], str] = {\n    ("/auth/login", "post"): "auth_login",\n    ("/auth/refresh", "post"): "auth_refresh",\n    ("/auth/logout", "post"): "auth_logout",\n    ("/api/meta", "get"): "meta_get_meta",\n    ("/api/meta/schemas", "get"): "meta_get_meta_schemas",\n    ("/api/settings", "get"): "settings_get_settings",\n    ("/api/settings", "put"): "settings_update_settings",\n    ("/api/analysis/run", "post"): "analysis_run_analysis",\n    ("/api/analysis/history", "get"): "analysis_list_analysis",\n}\n\n_HTTP_METHODS = {"get", "put", "post", "delete", "options", "head", "patch", "trace"}\n_SENSITIVE_FIELD_NAMES = {\n    "password",\n    "api_key",\n    "apikey",\n    "secret_key",\n    "access_token",\n    "refresh_token",\n    "client_secret",\n    "encryption_key",\n}\n_EXAMPLE_KEYS = {"default", "example", "examples"}\n\n\ndef iter_operations(schema: dict[str, Any]):\n    for path, path_item in schema.get("paths", {}).items():\n        if not isinstance(path_item, dict):\n            continue\n        for method, operation in path_item.items():\n            if method.lower() in _HTTP_METHODS and isinstance(operation, dict):\n                yield path, method.lower(), operation\n\n\ndef operation_id_map(schema: dict[str, Any]) -> dict[tuple[str, str], str]:\n    return {\n        (path, method): str(operation.get("operationId") or "")\n        for path, method, operation in iter_operations(schema)\n    }\n\n\ndef validate_operation_ids(schema: dict[str, Any]) -> None:\n    ids = [str(operation.get("operationId") or "") for _, _, operation in iter_operations(schema)]\n    missing = [item for item in ids if not item]\n    if missing:\n        raise ValueError("OpenAPI contains operation(s) without operationId")\n    duplicates = sorted(value for value, count in Counter(ids).items() if count > 1)\n    if duplicates:\n        raise ValueError(f"Duplicate OpenAPI operationId values: {', '.join(duplicates)}")\n\n    actual = operation_id_map(schema)\n    problems = []\n    for key, expected in CORE_OPERATION_IDS.items():\n        value = actual.get(key)\n        if value != expected:\n            problems.append(f"{key[1].upper()} {key[0]} expected {expected!r}, got {value!r}")\n    if problems:\n        raise ValueError("Stable OpenAPI operationId contract changed: " + "; ".join(problems))\n\n\ndef _sensitive_path(path: tuple[str, ...]) -> bool:\n    for part in path:\n        normalized = part.lower().replace("-", "_")\n        if normalized == "token_type":\n            continue\n        if normalized in _SENSITIVE_FIELD_NAMES:\n            return True\n        if any(normalized.endswith("_" + name) for name in _SENSITIVE_FIELD_NAMES):\n            return True\n    return False\n\n\ndef _nonempty_string_values(value: Any):\n    if isinstance(value, str):\n        if value.strip():\n            yield value.strip()\n    elif isinstance(value, list):\n        for item in value:\n            yield from _nonempty_string_values(item)\n    elif isinstance(value, dict):\n        for item in value.values():\n            yield from _nonempty_string_values(item)\n\n\ndef validate_no_secret_examples(schema: dict[str, Any]) -> None:\n    leaked: list[str] = []\n\n    def walk(value: Any, path: tuple[str, ...] = ()) -> None:\n        if isinstance(value, dict):\n            for key, child in value.items():\n                next_path = (*path, str(key))\n                if key in _EXAMPLE_KEYS and _sensitive_path(path):\n                    for literal in _nonempty_string_values(child):\n                        if literal not in {"***", "<redacted>", "REDACTED"}:\n                            leaked.append(".".join(path))\n                walk(child, next_path)\n        elif isinstance(value, list):\n            for index, child in enumerate(value):\n                walk(child, (*path, str(index)))\n\n    walk(schema)\n    if leaked:\n        raise ValueError("OpenAPI contains non-masked secret example/default values at: " + ", ".join(sorted(set(leaked))))\n\n    rendered = json.dumps(schema, sort_keys=True)\n    if "openapi-export-placeholder-key" in rendered:\n        raise ValueError("OpenAPI leaked the exporter's placeholder SECRET_KEY")\n\n\ndef validate_openapi_schema(schema: dict[str, Any]) -> None:\n    # FastAPI ships a Pydantic representation of the OpenAPI document; using it\n    # avoids adding a second validator dependency solely for export.\n    OpenAPI.model_validate(schema)\n    validate_operation_ids(schema)\n    validate_no_secret_examples(schema)\n\n\ndef render_openapi(schema: dict[str, Any]) -> str:\n    return json.dumps(schema, indent=2, sort_keys=True) + "\\n"\n\n\ndef build_validated_openapi() -> dict[str, Any]:\n    from backend.main import app\n\n    schema = app.openapi()\n    validate_openapi_schema(schema)\n    return schema\n''',
    encoding="utf-8",
)

# Keep the existing exporter structure and offline environment; only centralize
# schema validation/rendering around its current app.openapi() call.
replace(
    "backend/scripts/export-openapi.py",
    "import json\n",
    "",
)
replace(
    "backend/scripts/export-openapi.py",
    '''    from backend.main import app\n\n    destination = Path(sys.argv[1]) if len(sys.argv) > 1 else _REPO_ROOT / "frontend" / "openapi.json"\n    destination.parent.mkdir(parents=True, exist_ok=True)\n\n    schema = app.openapi()\n    # sort_keys keeps the output stable so a regenerated file only differs when\n    # the API actually changed.\n    destination.write_text(json.dumps(schema, indent=2, sort_keys=True) + "\\n", encoding="utf-8")\n''',
    '''    from backend.core.openapi_contract import build_validated_openapi, render_openapi\n\n    destination = Path(sys.argv[1]) if len(sys.argv) > 1 else _REPO_ROOT / "frontend" / "openapi.json"\n    destination.parent.mkdir(parents=True, exist_ok=True)\n\n    schema = build_validated_openapi()\n    # Stable rendering keeps generated-client diffs tied to API changes only.\n    destination.write_text(render_openapi(schema), encoding="utf-8")\n''',
)

Path("backend/tests/test_core/test_openapi_contract.py").write_text(
    '''from __future__ import annotations\n\nimport socket\n\nimport pytest\n\nfrom backend.core.openapi_contract import (\n    CORE_OPERATION_IDS,\n    build_validated_openapi,\n    operation_id_map,\n    render_openapi,\n    validate_no_secret_examples,\n    validate_openapi_schema,\n    validate_operation_ids,\n)\n\n\ndef test_openapi_is_valid_and_operation_ids_are_unique_and_stable():\n    schema = build_validated_openapi()\n    validate_openapi_schema(schema)\n    mapping = operation_id_map(schema)\n    for key, expected in CORE_OPERATION_IDS.items():\n        assert mapping[key] == expected\n\n\ndef test_duplicate_operation_id_is_rejected():\n    schema = {\n        "openapi": "3.1.0",\n        "info": {"title": "x", "version": "1"},\n        "paths": {\n            "/a": {"get": {"operationId": "same", "responses": {"200": {"description": "ok"}}}},\n            "/b": {"get": {"operationId": "same", "responses": {"200": {"description": "ok"}}}},\n        },\n    }\n    with pytest.raises(ValueError, match="Duplicate OpenAPI operationId"):\n        validate_operation_ids(schema)\n\n\ndef test_openapi_render_is_deterministic():\n    schema = build_validated_openapi()\n    first = render_openapi(schema)\n    second = render_openapi(build_validated_openapi())\n    assert first == second\n\n\ndef test_openapi_generation_does_not_open_database_or_network(monkeypatch):\n    def forbidden_connect(*_args, **_kwargs):\n        raise AssertionError("network access attempted during OpenAPI export")\n\n    monkeypatch.setattr(socket.socket, "connect", forbidden_connect)\n\n    from sqlalchemy.ext.asyncio import AsyncEngine\n\n    def forbidden_db_connect(*_args, **_kwargs):\n        raise AssertionError("database access attempted during OpenAPI export")\n\n    monkeypatch.setattr(AsyncEngine, "connect", forbidden_db_connect)\n    schema = build_validated_openapi()\n    assert schema["paths"]\n\n\ndef test_secret_examples_are_rejected_but_masked_values_are_allowed():\n    good = {"components": {"schemas": {"X": {"properties": {"api_key": {"example": "***"}}}}}}\n    validate_no_secret_examples(good)\n    bad = {"components": {"schemas": {"X": {"properties": {"api_key": {"example": "sk-live-secret"}}}}}}\n    with pytest.raises(ValueError, match="secret example/default"):\n        validate_no_secret_examples(bad)\n''',
    encoding="utf-8",
)
